:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #2a2a4a;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

h1 {
  font-size: 1.75rem;
  text-align: center;
  letter-spacing: 2px;
  color: var(--accent);
}

.hud {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.score-box {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

.value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
}

.status {
  font-size: 0.9rem;
  color: var(--muted);
  padding: 4px 12px;
  border: 1px solid var(--border);
  border-radius: 20px;
}

.board-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: #0d0d1a;
  border: 2px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(13, 13, 26, 0.92);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 20px;
  text-align: center;
}

.overlay.hidden { display: none; }

.overlay h2 {
  font-size: 1.4rem;
  color: var(--accent);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--muted);
}

.overlay strong { color: var(--text); }

.btn {
  font-family: var(--font);
  font-size: 1rem;
  padding: 10px 24px;
  border: 2px solid var(--accent);
  border-radius: 8px;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, transform 0.1s;
}

.btn:hover {
  background: var(--accent);
  color: var(--card);
}

.btn:active {
  transform: scale(0.96);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  background: transparent;
  color: var(--accent);
}

.controls {
  display: flex;
  gap: 12px;
}

.controls .btn { flex: 1; }

@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.4rem; }
  .value { font-size: 1.25rem; }
}

(function () {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const statusEl = document.getElementById('status');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText = document.getElementById('overlay-text');
  const overlayBtn = document.getElementById('overlay-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');

  const GRID = 20;
  const CELL = canvas.width / GRID;

  let snake, dir, nextDir, food, score, state, timer;

  const COLORS = {
    bg: '#0d0d1a',
    snake: '#4ecca3',
    head: '#7ef0c0',
    food: '#e94560',
    grid: '#1a1a2e'
  };

  function init() {
    snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    state = 'paused';
    scoreEl.textContent = '0';
    statusEl.textContent = 'Paused';
    pauseBtn.textContent = 'Pause';
    pauseBtn.disabled = true;
    overlayBtn.textContent = 'Start';
    overlayTitle.textContent = 'How to Play';
    overlayText.innerHTML = 'Use <strong>Arrow Keys</strong> to move.<br>Eat the red food to grow.<br>Press <strong>Start</strong> to begin.';
    overlay.classList.remove('hidden');
    spawnFood();
    draw();
    clearInterval(timer);
    timer = null;
  }

  function spawnFood() {
    let pos;
    do {
      pos = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function draw() {
    ctx.fillStyle = COLORS.bg;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = COLORS.grid;
    ctx.lineWidth = 1;
    for (let i = 1; i < GRID; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL, 0);
      ctx.lineTo(i * CELL, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL);
      ctx.lineTo(canvas.width, i * CELL);
      ctx.stroke();
    }

    ctx.fillStyle = COLORS.food;
    ctx.fillRect(food.x * CELL + 1, food.y * CELL + 1, CELL - 2, CELL - 2);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? COLORS.head : COLORS.snake;
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function step() {
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID) {
      return gameOver();
    }

    if (snake.some((s, i) => i < snake.length - 1 && s.x === head.x && s.y === head.y)) {
      return gameOver();
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = score;
      spawnFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function gameOver() {
    clearInterval(timer);
    timer = null;
    state = 'over';
    statusEl.textContent = 'Game Over';
    pauseBtn.disabled = true;
    overlayTitle.textContent = 'Game Over';
    overlayText.innerHTML = 'Final Score: <strong>' + score + '</strong><br>Press Restart to play again.';
    overlayBtn.textContent = 'Restart';
    overlay.classList.remove('hidden');
  }

  function start() {
    if (state === 'running') return;
    state = 'running';
    statusEl.textContent = 'Running';
    pauseBtn.textContent = 'Pause';
    pauseBtn.disabled = false;
    overlay.classList.add('hidden');
    clearInterval(timer);
    timer = setInterval(step, 120);
  }

  function pause() {
    if (state !== 'running') return;
    state = 'paused';
    statusEl.textContent = 'Paused';
    pauseBtn.textContent = 'Resume';
    clearInterval(timer);
    timer = null;
  }

  function resume() {
    if (state !== 'paused') return;
    state = 'running';
    statusEl.textContent = 'Running';
    pauseBtn.textContent = 'Pause';
    clearInterval(timer);
    timer = setInterval(step, 120);
  }

  function restart() {
    init();
    start();
  }

  function togglePause() {
    if (state === 'running') pause();
    else if (state === 'paused') resume();
    else if (state === 'over') restart();
  }

  document.addEventListener('keydown', (e) => {
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(key)) {
      e.preventDefault();
      if (state !== 'running') return;
      let nd = { x: 0, y: 0 };
      if (key === 'ArrowUp') nd = { x: 0, y: -1 };
      else if (key === 'ArrowDown') nd = { x: 0, y: 1 };
      else if (key === 'ArrowLeft') nd = { x: -1, y: 0 };
      else if (key === 'ArrowRight') nd = { x: 1, y: 0 };
      if (nd.x === -dir.x && nd.y === -dir.y) return;
      nextDir = nd;
    } else if (key === ' ' || key === 'p' || key === 'P') {
      e.preventDefault();
      togglePause();
    }
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);
  overlayBtn.addEventListener('click', () => {
    if (state === 'over') restart();
    else start();
  });

  init();
})();
